import {AllKnownTypes, type KnownType} from '@github-ui/issue-fields-shared/issue-field'
import {ActionList, ActionMenu, FormControl} from '@primer/react'

import {Resources} from '../constants/strings'

type IssueFieldDataTypeProps = {
  disabled?: boolean
  type: KnownType
  setType: (type: KnownType) => void
  ref?: React.Ref<HTMLButtonElement>
}

export function IssueFieldDataType({ref: forwardedRef, type, setType, disabled = false}: IssueFieldDataTypeProps) {
  return (
    <FormControl disabled={disabled}>
      <FormControl.Label>{Resources.typeLabel}</FormControl.Label>
      <ActionMenu>
        <ActionMenu.Button ref={forwardedRef} leadingVisual={type.icon} disabled={disabled}>
          {type.displayName}
        </ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList selectionVariant="single" role="menu" aria-label="Item">
            {AllKnownTypes.map(knownType => (
              <ActionList.Item
                key={knownType.type}
                role="menuitemradio"
                selected={type === knownType}
                aria-checked={type === knownType}
                onSelect={() => setType(knownType)}
              >
                <ActionList.LeadingVisual>
                  <knownType.icon size={16} />
                </ActionList.LeadingVisual>
                {knownType.displayName}
              </ActionList.Item>
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </FormControl>
  )
}
