import {Button} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useCallback, useState} from 'react'

import {Resources} from '../constants/strings'
import styles from './IssueFieldActions.module.css'
import {IssueFieldEditConfirmationDialog} from './IssueFieldEditConfirmationDialog'
import {IssueFieldsDelete} from './IssueFieldsDelete'

type IssueFieldActionsProps = {
  disabled?: boolean
  confirmLabel: string
  cancelLabel?: string
  onConfirm: () => void
  onCancel: () => void
  initialData: {
    name: string
    id: string
    organization: string
  }
  successMessage?: boolean
  isCreateNew?: boolean
  showGlobalWarning?: boolean
}

export function IssueFieldActions(props: IssueFieldActionsProps) {
  const {
    disabled = false,
    onCancel,
    onConfirm,
    cancelLabel = Resources.cancelButton,
    confirmLabel,
    initialData,
    successMessage,
    isCreateNew,
    showGlobalWarning,
  } = props
  const [isConfirmationDialogOpen, setIsConfirmationDialogOpen] = useState(false)

  const handleConfirmClick = useCallback(() => {
    if (!isCreateNew && showGlobalWarning) {
      setIsConfirmationDialogOpen(true)
    } else {
      onConfirm()
    }
  }, [isCreateNew, showGlobalWarning, onConfirm])

  const handleConfirmationDialogClose = useCallback(() => {
    setIsConfirmationDialogOpen(false)
  }, [])

  const handleConfirmationDialogConfirm = useCallback(() => {
    onConfirm()
  }, [onConfirm])

  return (
    <div className={styles.container}>
      {!isCreateNew && showGlobalWarning && (
        <div className={styles.globalWarning} role="alert">
          <InlineMessage variant="warning" size="small">
            {Resources.globalEditWarning}
          </InlineMessage>
        </div>
      )}
      <div className={styles.actionsContainer}>
        <div className={styles.saveCancelContainer}>
          <Button
            variant="primary"
            onClick={handleConfirmClick}
            data-testid="issue-type-confirm-button"
            disabled={disabled}
          >
            {confirmLabel}
          </Button>
          <Button onClick={onCancel} data-testid="issue-type-cancel-button" disabled={disabled}>
            {cancelLabel}
          </Button>
          <div className={styles.confirmationContainer}>
            {successMessage && (
              <InlineMessage className={styles.inlineMessage} variant="success">
                {Resources.saveComplete}
              </InlineMessage>
            )}
          </div>
        </div>
        {!isCreateNew && (
          <IssueFieldsDelete
            issueFieldName={initialData.name}
            issueFieldId={initialData.id}
            organization={initialData.organization}
          />
        )}
      </div>
      <IssueFieldEditConfirmationDialog
        isOpen={isConfirmationDialogOpen}
        onClose={handleConfirmationDialogClose}
        onConfirm={handleConfirmationDialogConfirm}
      />
    </div>
  )
}
