import type {FieldVisibilityPermissions} from '@github-ui/issue-fields-shared/issue-field'
import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'

export interface CreateIssueFieldOptionPayload {
  name: string
  color: string
  description?: string
  priority: number
}

export interface CreateIssueFieldPayload {
  name: string
  data_type: string
  description: string
  priority?: number
  options?: CreateIssueFieldOptionPayload[]
  pinnedIssueTypeIds?: string[]
  pinToNoTypeIssues?: boolean
  visibility: FieldVisibilityPermissions
}

export interface CreateIssueFieldResponse {
  id: string
  name: string
  data_type: string
  description: string
  priority?: number
  visibility: FieldVisibilityPermissions
}

export async function createIssueFieldRequest(
  payload: CreateIssueFieldPayload,
  params: {orgName: string},
): Promise<CreateIssueFieldResponse> {
  // Validate single_select fields have at least one option
  if (payload.data_type === 'single_select' && (!payload.options || payload.options.length === 0)) {
    throw new Error('Single select fields must have at least one option')
  }

  const pathname = `/organizations/${params.orgName}/settings/issue-fields`

  // Create FormData for form submission
  const formData = new FormData()
  formData.append('name', payload.name)
  formData.append('data_type', payload.data_type)
  formData.append('description', payload.description)
  if (payload.priority !== undefined) {
    formData.append('priority', payload.priority.toString())
  }

  // Add options if provided (for single_select fields)
  if (payload.options && payload.options.length > 0) {
    for (const [index, option] of payload.options.entries()) {
      formData.append(`options[${index}][name]`, option.name)
      formData.append(`options[${index}][color]`, option.color)
      formData.append(`options[${index}][priority]`, option.priority.toString())
      if (option.description) {
        formData.append(`options[${index}][description]`, option.description)
      }
    }
  }

  // Add pinned issue type IDs if provided
  if (payload.pinnedIssueTypeIds !== undefined) {
    for (const typeId of payload.pinnedIssueTypeIds) {
      formData.append('pinned_issue_type_ids[]', typeId)
    }
  }
  // Add pin to no type issues flag if provided
  if (payload.pinToNoTypeIssues !== undefined) {
    formData.append('pin_to_no_type_issues', payload.pinToNoTypeIssues.toString())
  }

  formData.append('visibility', payload.visibility)

  const init = {
    method: 'POST',
    body: formData,
  }

  const response = await reactFetch(pathname, init)

  if (!response.ok) {
    // try to extract error details from the response body if there are any
    let errorDetails = ''
    try {
      const data = await response.json()
      if (data && data.error) errorDetails = `: ${data.error}`
    } catch {
      // ignore JSON parsing errors for non-JSON responses
    }
    throw new ResponseError(`Failed to create issue field${errorDetails}`, response)
  }

  return response.json()
}

export function useCreateIssueFieldMutation(organization: string) {
  return useMutation({
    mutationFn: async (payload: CreateIssueFieldPayload) => {
      return createIssueFieldRequest(payload, {orgName: organization})
    },
  })
}
