import {
  createIssueTypePickerItemLeadingVisual,
  NoTypeIndicator,
} from '@github-ui/item-picker-issue-type/IssueTypeIndicators'
import {AlertIcon} from '@primer/octicons-react'
import {ActionList, Dialog} from '@primer/react'
import type {RefObject} from 'react'
import {useCallback, useEffect, useMemo, useState} from 'react'

import {MAX_PINNED_FIELDS} from '../constants/constants'
import {Resources} from '../constants/strings'
import type {IssueTypeWithPinnedCount} from '../types/field-visibility'
import styles from './IssueFieldPinToIssueTypesDialog.module.css'

type IssueFieldPinToIssueTypesDialogProps = {
  isOpen: boolean
  allIssueTypes: IssueTypeWithPinnedCount[]
  selectedIssueTypeIds: string[]
  pinnedToNoTypeIssues: boolean
  onClose: () => void
  onSave: (selectedIssueTypeIds: string[], pinnedToNoTypeIssues: boolean) => void
  returnFocusRef?: RefObject<HTMLButtonElement | null>
  initialPinnedIssueTypeIds?: string[]
  initialPinnedToNoTypeIssues?: boolean
}

export function IssueFieldPinToIssueTypesDialog({
  isOpen,
  allIssueTypes,
  selectedIssueTypeIds,
  pinnedToNoTypeIssues,
  onClose,
  onSave,
  returnFocusRef,
  initialPinnedIssueTypeIds,
  initialPinnedToNoTypeIssues,
}: IssueFieldPinToIssueTypesDialogProps) {
  const [localSelectedIds, setLocalSelectedIds] = useState<Set<string>>(() => new Set(selectedIssueTypeIds))
  const [localPinnedToNoTypeIssues, setLocalPinnedToNoTypeIssues] = useState<boolean>(pinnedToNoTypeIssues)

  // Filter out synthetic "no type" entry (null ID) and extract its pinned count
  const {validIssueTypes, noTypePinnedFieldsCount} = useMemo(() => {
    const noTypeEntry = allIssueTypes.find(t => !t.id)
    const filtered = allIssueTypes.filter((t): t is IssueTypeWithPinnedCount & {id: string} => Boolean(t.id))
    return {
      validIssueTypes: filtered,
      noTypePinnedFieldsCount: noTypeEntry?.pinnedFieldsCount,
    }
  }, [allIssueTypes])

  // Sync local state when dialog opens
  useEffect(() => {
    if (isOpen) {
      setLocalSelectedIds(new Set(selectedIssueTypeIds))
      setLocalPinnedToNoTypeIssues(pinnedToNoTypeIssues)
    }
    // Only reset when dialog opens, not when props change during editing
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen])

  const handleIssueTypeToggle = useCallback((issueTypeId: string) => {
    setLocalSelectedIds(prev => {
      const newSet = new Set(prev)
      if (newSet.has(issueTypeId)) {
        newSet.delete(issueTypeId)
      } else {
        newSet.add(issueTypeId)
      }
      return newSet
    })
  }, [])

  const handleNoTypeToggle = useCallback(() => {
    setLocalPinnedToNoTypeIssues(prev => !prev)
  }, [])

  const handleSave = useCallback(() => {
    onSave(Array.from(localSelectedIds), localPinnedToNoTypeIssues)
    onClose()
  }, [localSelectedIds, localPinnedToNoTypeIssues, onSave, onClose])

  if (!isOpen) {
    return null
  }

  const isNoTypeAtMaxCapacity =
    noTypePinnedFieldsCount !== undefined &&
    noTypePinnedFieldsCount >= MAX_PINNED_FIELDS &&
    !(initialPinnedToNoTypeIssues ?? pinnedToNoTypeIssues)

  return (
    <Dialog
      title={Resources.fieldPinToIssueTypesDialogTitle}
      subtitle={Resources.fieldPinToIssueTypesDialogSubtitle}
      width="large"
      onClose={onClose}
      returnFocusRef={returnFocusRef}
      renderFooter={() => (
        <Dialog.Footer className={styles.footer}>
          <Dialog.Buttons
            buttons={[
              {buttonType: 'default', content: Resources.cancelButton, onClick: onClose},
              {buttonType: 'primary', content: Resources.fieldPinToIssueTypesDialogSaveButton, onClick: handleSave},
            ]}
          />
        </Dialog.Footer>
      )}
      renderBody={() => (
        <ActionList selectionVariant="multiple" role="listbox" aria-label={Resources.fieldPinToIssueTypesDialogTitle}>
          {/* Issues without a type */}
          <ActionList.Item
            role="option"
            selected={localPinnedToNoTypeIssues}
            aria-selected={localPinnedToNoTypeIssues}
            onSelect={handleNoTypeToggle}
            disabled={isNoTypeAtMaxCapacity}
          >
            <ActionList.LeadingVisual>
              <NoTypeIndicator />
            </ActionList.LeadingVisual>
            {Resources.fieldPinToIssueTypesNoType}
            <ActionList.Description variant="block">
              {isNoTypeAtMaxCapacity
                ? Resources.fieldPinToIssueTypesMaxPinnedFields(MAX_PINNED_FIELDS)
                : Resources.fieldPinToIssueTypesNoTypeDescription}
            </ActionList.Description>
            {isNoTypeAtMaxCapacity && (
              <ActionList.TrailingVisual>
                <AlertIcon />
              </ActionList.TrailingVisual>
            )}
          </ActionList.Item>

          {/* Types section */}
          {validIssueTypes.length > 0 && (
            <ActionList.Group>
              <ActionList.GroupHeading variant="filled">
                {Resources.fieldPinToIssueTypesTypesHeader}
              </ActionList.GroupHeading>
              {validIssueTypes.map(issueType => {
                const IssueTypeIndicator = createIssueTypePickerItemLeadingVisual(issueType.color)
                const isSelected = localSelectedIds.has(issueType.id)
                // Allow re-selecting items that were initially pinned (before any local changes)
                const wasInitiallyPinned = (initialPinnedIssueTypeIds ?? selectedIssueTypeIds).includes(issueType.id)
                const isAtMaxCapacity =
                  issueType.pinnedFieldsCount !== undefined &&
                  issueType.pinnedFieldsCount >= MAX_PINNED_FIELDS &&
                  !wasInitiallyPinned
                return (
                  <ActionList.Item
                    key={issueType.id}
                    role="option"
                    selected={isSelected}
                    aria-selected={isSelected}
                    onSelect={() => handleIssueTypeToggle(issueType.id)}
                    disabled={isAtMaxCapacity}
                  >
                    <ActionList.LeadingVisual>
                      <IssueTypeIndicator />
                    </ActionList.LeadingVisual>
                    {issueType.name}
                    {(isAtMaxCapacity || issueType.description) && (
                      <ActionList.Description variant="block">
                        {isAtMaxCapacity
                          ? Resources.fieldPinToIssueTypesMaxPinnedFields(MAX_PINNED_FIELDS)
                          : issueType.description}
                      </ActionList.Description>
                    )}
                    {isAtMaxCapacity && (
                      <ActionList.TrailingVisual>
                        <AlertIcon />
                      </ActionList.TrailingVisual>
                    )}
                  </ActionList.Item>
                )
              })}
            </ActionList.Group>
          )}
        </ActionList>
      )}
    />
  )
}
