import {Heading} from '@primer/react'
import type {FC, ReactNode} from 'react'

import styles from './Title.module.css'

type TitleProps = {
  children: ReactNode
  showBorder?: boolean
}

export const Title: FC<TitleProps> = ({children, showBorder = true}) => {
  return (
    <Heading as="h2" className={`${styles.heading}${showBorder ? ` ${styles.border}` : ''}`}>
      {children}
    </Heading>
  )
}
