import {Dialog} from '@primer/react'
import type {RefObject} from 'react'
import {useCallback} from 'react'

import {Resources} from '../constants/strings'
import styles from './IssueFieldNotPinnedConfirmationDialog.module.css'

type IssueFieldNotPinnedConfirmationDialogProps = {
  isOpen: boolean
  onClose: () => void
  onLeaveHidden: () => void
  cancelReturnFocusRef?: RefObject<HTMLButtonElement | null>
}

export function IssueFieldNotPinnedConfirmationDialog({
  isOpen,
  onClose,
  onLeaveHidden,
  cancelReturnFocusRef,
}: IssueFieldNotPinnedConfirmationDialogProps) {
  const handleLeaveHidden = useCallback(() => {
    onLeaveHidden()
    onClose()
  }, [onLeaveHidden, onClose])

  if (!isOpen) {
    return null
  }

  return (
    <Dialog
      title={Resources.fieldNotPinnedConfirmationDialogTitle}
      width="large"
      onClose={onClose}
      returnFocusRef={cancelReturnFocusRef}
      footerButtons={[
        {
          buttonType: 'default',
          content: Resources.fieldNotPinnedConfirmationCancelButton,
          onClick: onClose,
        },
        {
          buttonType: 'danger',
          content: Resources.fieldNotPinnedConfirmationLeaveHiddenButton,
          onClick: handleLeaveHidden,
        },
      ]}
    >
      <div className={styles.body}>{Resources.fieldNotPinnedConfirmationDialogBody}</div>
    </Dialog>
  )
}
