import type {FieldVisibilityPermissions} from '@github-ui/issue-fields-shared/issue-field'
import {GlobeIcon, LockIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, FormControl} from '@primer/react'
import {useMemo} from 'react'

import {Resources} from '../constants/strings'
import styles from './IssueFieldVisibilityPermissions.module.css'

interface IssueFieldVisibilityPermissionsProps {
  fieldVisibilityPermissions?: FieldVisibilityPermissions
  onVisibilityPermissionsChange?: (visibility: FieldVisibilityPermissions) => void
  disabled?: boolean
}

export function IssueFieldVisibilityPermissions({
  fieldVisibilityPermissions = 'org_only',
  onVisibilityPermissionsChange,
  disabled = false,
}: IssueFieldVisibilityPermissionsProps) {
  const handleChange = (selected: FieldVisibilityPermissions) => {
    onVisibilityPermissionsChange?.(selected)
  }

  const permissionOptions = useMemo(
    () => [
      {
        key: 'org_only' as const,
        label: Resources.fieldVisibilityPermissionsOrganizationOnlyLabel,
        description: Resources.fieldVisibilityPermissionsOrganizationOnlyDescription,
        icon: LockIcon,
      },
      {
        key: 'all' as const,
        label: Resources.fieldVisibilityPermissionsPublicLabel,
        description: Resources.fieldVisibilityPermissionsPublicDescription,
        icon: GlobeIcon,
      },
    ],
    [],
  )

  return (
    <div className={styles.container}>
      <div className={styles.content}>
        <span className={styles.heading}>{Resources.fieldVisibilityPermissionsLabel}</span>
        <p className={styles.description}>{Resources.fieldVisibilityPermissionsDescription}</p>
      </div>

      <FormControl disabled={disabled} className={styles.selector}>
        <FormControl.Label visuallyHidden>{Resources.fieldVisibilityPermissionsLabel}</FormControl.Label>
        <ActionMenu>
          <ActionMenu.Button
            leadingVisual={fieldVisibilityPermissions === 'org_only' ? LockIcon : GlobeIcon}
            disabled={disabled}
          >
            {fieldVisibilityPermissions === 'org_only'
              ? Resources.fieldVisibilityPermissionsOrganizationOnlyLabel
              : Resources.fieldVisibilityPermissionsPublicLabel}
          </ActionMenu.Button>
          <ActionMenu.Overlay align="end" className={styles.actionList}>
            <ActionList selectionVariant="single" role="listbox" aria-label={Resources.fieldVisibilityPermissionsLabel}>
              {permissionOptions.map(option => (
                <ActionList.Item
                  key={option.key}
                  role="option"
                  selected={fieldVisibilityPermissions === option.key}
                  aria-selected={fieldVisibilityPermissions === option.key}
                  onSelect={() => handleChange(option.key)}
                >
                  <ActionList.LeadingVisual>{option.icon && <option.icon size={16} />}</ActionList.LeadingVisual>
                  {option.label}
                  <ActionList.Description variant="block">{option.description}</ActionList.Description>
                </ActionList.Item>
              ))}
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      </FormControl>
    </div>
  )
}
